"""Core service surface for TestLattice.

The catalog keeps suites and cases in memory; all state is lost when the
process restarts. Access is guarded by a lock because the HTTP layer runs
on a threading server.
"""

from __future__ import annotations

import copy
import threading
from collections.abc import Mapping

from . import __version__

ALLOWED_KINDS = ("unit", "api", "browser", "contract")
DEFAULT_TIMEOUT_SECONDS = 300
MIN_TIMEOUT_SECONDS = 1
MAX_TIMEOUT_SECONDS = 86400


class ApiError(Exception):
    """An error that maps directly onto an HTTP error response."""

    def __init__(self, status: int, code: str, message: str) -> None:
        super().__init__(message)
        self.status = status
        self.code = code
        self.message = message


def _validation(message: str) -> ApiError:
    return ApiError(400, "validation_error", message)


def _clean_text(value: object, field: str) -> str:
    """Validate id/name: string that is non-empty after trimming."""
    if not isinstance(value, str):
        raise _validation(f"{field} must be a string")
    cleaned = value.strip()
    if not cleaned:
        raise _validation(f"{field} must not be empty")
    return cleaned


def _reference(value: object, field: str) -> str:
    if not isinstance(value, str) or not value:
        raise _validation(f"{field} must be a non-empty string")
    return value


class Service:
    """In-memory catalog plus process health reporting."""

    name = "testlattice"
    version = __version__

    def __init__(self) -> None:
        self._lock = threading.RLock()
        self._suites: dict[str, dict] = {}
        self._cases: dict[str, dict] = {}

    def health(self) -> dict[str, str]:
        return {"status": "ok", "service": self.name, "version": self.version}

    # -- suites ---------------------------------------------------------

    def create_suite(self, payload: object) -> dict:
        if not isinstance(payload, dict):
            raise _validation("request body must be a JSON object")
        unknown = set(payload) - {"id", "name", "parent_id"}
        if unknown:
            raise _validation(f"unknown fields: {', '.join(sorted(unknown))}")
        if "id" not in payload:
            raise _validation("id is required")
        if "name" not in payload:
            raise _validation("name is required")

        suite_id = _clean_text(payload["id"], "id")
        name = _clean_text(payload["name"], "name")
        parent_id = None
        if "parent_id" in payload and payload["parent_id"] is not None:
            parent_id = _reference(payload["parent_id"], "parent_id")

        with self._lock:
            if suite_id in self._suites:
                raise ApiError(409, "suite_exists", f"suite {suite_id!r} already exists")
            if parent_id is not None:
                if parent_id == suite_id:
                    raise _validation("suite must not reference itself as parent")
                if parent_id not in self._suites:
                    raise ApiError(404, "suite_not_found", f"suite {parent_id!r} not found")
                # Walk the ancestor chain; reaching the new id would be a cycle.
                ancestor = self._suites[parent_id].get("parent_id")
                seen = {parent_id}
                while ancestor is not None:
                    if ancestor == suite_id:
                        raise _validation("suite hierarchy must not contain a cycle")
                    if ancestor in seen or ancestor not in self._suites:
                        break
                    seen.add(ancestor)
                    ancestor = self._suites[ancestor].get("parent_id")

            suite = {"id": suite_id, "name": name, "parent_id": parent_id}
            self._suites[suite_id] = suite
            return copy.deepcopy(suite)

    def get_suite(self, suite_id: str) -> dict:
        with self._lock:
            suite = self._suites.get(suite_id)
            if suite is None:
                raise ApiError(404, "suite_not_found", f"suite {suite_id!r} not found")
            return copy.deepcopy(suite)

    def list_suites(self) -> list[dict]:
        """Depth-first ordering: parents before children, creation order per level."""
        with self._lock:
            children: dict[str, list[str]] = {}
            for suite in self._suites.values():
                children.setdefault(suite["parent_id"], []).append(suite["id"])

            result: list[dict] = []

            def emit(suite_id: str) -> None:
                result.append(copy.deepcopy(self._suites[suite_id]))
                for child_id in children.get(suite_id, ()):
                    emit(child_id)

            for root_id in children.get(None, ()):
                emit(root_id)
            # Defensive: suites whose parent vanished still surface deterministically.
            rooted = {s["id"] for s in result}
            for suite_id in self._suites:
                if suite_id not in rooted:
                    emit(suite_id)
            return result

    def delete_suite(self, suite_id: str) -> None:
        with self._lock:
            if suite_id not in self._suites:
                raise ApiError(404, "suite_not_found", f"suite {suite_id!r} not found")

            subtree = {suite_id}
            frontier = [suite_id]
            while frontier:
                current = frontier.pop()
                for other in self._suites.values():
                    if other["parent_id"] == current and other["id"] not in subtree:
                        subtree.add(other["id"])
                        frontier.append(other["id"])

            for suite in self._suites.values():
                if suite["id"] in subtree and suite["id"] != suite_id:
                    raise ApiError(409, "suite_not_empty", f"suite {suite_id!r} is not empty")
            for case in self._cases.values():
                if case["suite_id"] in subtree:
                    raise ApiError(409, "suite_not_empty", f"suite {suite_id!r} is not empty")

            del self._suites[suite_id]

    # -- cases ----------------------------------------------------------

    def _validate_case(self, payload: object) -> dict:
        if not isinstance(payload, dict):
            raise _validation("request body must be a JSON object")
        allowed = {"id", "name", "suite_id", "kind", "steps", "tags", "enabled", "timeout_seconds"}
        unknown = set(payload) - allowed
        if unknown:
            raise _validation(f"unknown fields: {', '.join(sorted(unknown))}")
        for field in ("id", "name", "suite_id", "kind", "steps"):
            if field not in payload:
                raise _validation(f"{field} is required")

        case_id = _clean_text(payload["id"], "id")
        name = _clean_text(payload["name"], "name")
        suite_id = _reference(payload["suite_id"], "suite_id")

        kind = payload["kind"]
        if not isinstance(kind, str) or kind not in ALLOWED_KINDS:
            raise _validation(f"kind must be one of: {', '.join(ALLOWED_KINDS)}")

        steps = payload["steps"]
        if not isinstance(steps, list) or not steps:
            raise _validation("steps must be a non-empty array")
        for index, step in enumerate(steps):
            if not isinstance(step, dict):
                raise _validation(f"steps[{index}] must be a JSON object")
            action = step.get("action")
            if not isinstance(action, str) or action == "":
                raise _validation(f"steps[{index}].action must be a non-empty string")

        tags: list[str] = []
        if "tags" in payload and payload["tags"] is not None:
            raw_tags = payload["tags"]
            if not isinstance(raw_tags, list):
                raise _validation("tags must be an array")
            for index, tag in enumerate(raw_tags):
                if not isinstance(tag, str) or tag == "":
                    raise _validation(f"tags[{index}] must be a non-empty string")
                if tag not in tags:
                    tags.append(tag)

        enabled = True
        if "enabled" in payload and payload["enabled"] is not None:
            if not isinstance(payload["enabled"], bool):
                raise _validation("enabled must be a boolean")
            enabled = payload["enabled"]

        timeout = DEFAULT_TIMEOUT_SECONDS
        if "timeout_seconds" in payload and payload["timeout_seconds"] is not None:
            value = payload["timeout_seconds"]
            if isinstance(value, bool) or not isinstance(value, int):
                raise _validation("timeout_seconds must be an integer")
            if not MIN_TIMEOUT_SECONDS <= value <= MAX_TIMEOUT_SECONDS:
                raise _validation(
                    f"timeout_seconds must be between {MIN_TIMEOUT_SECONDS} and {MAX_TIMEOUT_SECONDS}"
                )
            timeout = value

        return {
            "id": case_id,
            "name": name,
            "suite_id": suite_id,
            "kind": kind,
            "steps": copy.deepcopy(steps),
            "tags": tags,
            "enabled": enabled,
            "timeout_seconds": timeout,
        }

    def create_case(self, payload: object) -> dict:
        case = self._validate_case(payload)
        with self._lock:
            if case["id"] in self._cases:
                raise ApiError(409, "case_exists", f"case {case['id']!r} already exists")
            if case["suite_id"] not in self._suites:
                raise ApiError(404, "suite_not_found", f"suite {case['suite_id']!r} not found")
            self._cases[case["id"]] = case
            return copy.deepcopy(case)

    def get_case(self, case_id: str) -> dict:
        with self._lock:
            case = self._cases.get(case_id)
            if case is None:
                raise ApiError(404, "case_not_found", f"case {case_id!r} not found")
            return copy.deepcopy(case)

    def list_cases(self, filters: Mapping[str, object]) -> list[dict]:
        suite_id = filters.get("suite_id")
        include_descendants = bool(filters.get("include_descendants", False))
        kind = filters.get("kind")
        enabled = filters.get("enabled")
        required_tags = filters.get("tags", ())

        with self._lock:
            allowed_suites: set[str] | None = None
            if suite_id is not None:
                if suite_id not in self._suites:
                    raise ApiError(404, "suite_not_found", f"suite {suite_id!r} not found")
                allowed_suites = {suite_id}
                if include_descendants:
                    frontier = [suite_id]
                    while frontier:
                        current = frontier.pop()
                        for suite in self._suites.values():
                            if suite["parent_id"] == current and suite["id"] not in allowed_suites:
                                allowed_suites.add(suite["id"])
                                frontier.append(suite["id"])

            result: list[dict] = []
            for case in self._cases.values():
                if allowed_suites is not None and case["suite_id"] not in allowed_suites:
                    continue
                if kind is not None and case["kind"] != kind:
                    continue
                if enabled is not None and case["enabled"] != enabled:
                    continue
                if required_tags and not all(tag in case["tags"] for tag in required_tags):
                    continue
                result.append(copy.deepcopy(case))
            return result

    def delete_case(self, case_id: str) -> None:
        with self._lock:
            if case_id not in self._cases:
                raise ApiError(404, "case_not_found", f"case {case_id!r} not found")
            del self._cases[case_id]

"""HTTP entry point for TestLattice."""

from __future__ import annotations

import argparse
import json
import os
from http.server import BaseHTTPRequestHandler, ThreadingHTTPServer
from urllib.parse import parse_qs, unquote, urlsplit

from .service import ALLOWED_KINDS, ApiError, Service


def env_address() -> tuple[str, int]:
    raw = os.environ.get("TESTLATTICE_ADDR", "127.0.0.1:8080")
    host, _, port = raw.rpartition(":")
    if not host or not port.isdigit():
        raise SystemExit(f"invalid TESTLATTICE_ADDR: {raw!r}")
    return host, int(port)


def _first(values: dict[str, list[str]], key: str) -> object:
    return values[key][0] if key in values else None


def _resource_id(path: str, prefix: str) -> str | None:
    if not path.startswith(prefix):
        return None
    tail = unquote(path[len(prefix):])
    if not tail or "/" in tail:
        return None
    return tail


class Handler(BaseHTTPRequestHandler):
    service = Service()

    def send_json(self, status: int, payload: object) -> None:
        body = json.dumps(payload, ensure_ascii=False, sort_keys=True).encode("utf-8")
        self.send_response(status)
        self.send_header("Content-Type", "application/json; charset=utf-8")
        self.send_header("Content-Length", str(len(body)))
        self.end_headers()
        self.wfile.write(body)

    def send_no_content(self) -> None:
        self.send_response(204)
        self.send_header("Content-Length", "0")
        self.end_headers()

    def send_error_body(self, status: int, code: str, message: str) -> None:
        self.send_json(status, {"error": {"code": code, "message": message}})

    def send_api_error(self, error: ApiError) -> None:
        self.send_error_body(error.status, error.code, error.message)

    def read_body(self) -> object:
        length_raw = self.headers.get("Content-Length")
        try:
            length = int(length_raw) if length_raw is not None else 0
        except ValueError:
            raise ApiError(400, "invalid_json", "request body is not valid JSON")
        raw = self.rfile.read(length) if length > 0 else b""
        try:
            return json.loads(raw)
        except (json.JSONDecodeError, UnicodeDecodeError):
            raise ApiError(400, "invalid_json", "request body is not valid JSON")

    # -- GET ------------------------------------------------------------

    def do_GET(self) -> None:
        if self.path == "/healthz":
            self.send_json(200, self.service.health())
            return
        parts = urlsplit(self.path)
        path = parts.path
        if path == "/v1/suites":
            self.handle_list_suites()
            return
        suite_id = _resource_id(path, "/v1/suites/")
        if suite_id is not None:
            self.handle_get_suite(suite_id)
            return
        if path == "/v1/cases":
            self.handle_list_cases(parts.query)
            return
        case_id = _resource_id(path, "/v1/cases/")
        if case_id is not None:
            self.handle_get_case(case_id)
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def handle_get_suite(self, suite_id: str) -> None:
        try:
            self.send_json(200, self.service.get_suite(suite_id))
        except ApiError as error:
            self.send_api_error(error)

    def handle_list_suites(self) -> None:
        self.send_json(200, self.service.list_suites())

    def handle_get_case(self, case_id: str) -> None:
        try:
            self.send_json(200, self.service.get_case(case_id))
        except ApiError as error:
            self.send_api_error(error)

    def handle_list_cases(self, query: str) -> None:
        try:
            filters = self.parse_case_filters(parse_qs(query, keep_blank_values=True))
            self.send_json(200, self.service.list_cases(filters))
        except ApiError as error:
            self.send_api_error(error)

    @staticmethod
    def parse_case_filters(values: dict[str, list[str]]) -> dict[str, object]:
        filters: dict[str, object] = {}

        suite_id = _first(values, "suite_id")
        if suite_id is not None:
            if suite_id == "":
                raise ApiError(400, "validation_error", "suite_id must be a non-empty string")
            filters["suite_id"] = suite_id

        if "include_descendants" in values:
            raw = values["include_descendants"][0]
            if raw not in ("true", "false"):
                raise ApiError(400, "validation_error", "include_descendants must be true or false")
            filters["include_descendants"] = raw == "true"

        kind = _first(values, "kind")
        if kind is not None:
            if kind not in ALLOWED_KINDS:
                raise ApiError(400, "validation_error", f"kind must be one of: {', '.join(ALLOWED_KINDS)}")
            filters["kind"] = kind

        if "enabled" in values:
            raw = values["enabled"][0]
            if raw not in ("true", "false"):
                raise ApiError(400, "validation_error", "enabled must be true or false")
            filters["enabled"] = raw == "true"

        if "tags" in values:
            tags: list[str] = []
            for raw in values["tags"]:
                for tag in raw.split(","):
                    if tag == "":
                        raise ApiError(400, "validation_error", "tags must be non-empty strings")
                    if tag not in tags:
                        tags.append(tag)
            filters["tags"] = tags

        if filters.get("include_descendants") and "suite_id" not in filters:
            raise ApiError(
                400,
                "validation_error",
                "include_descendants can only be used together with suite_id",
            )
        return filters

    # -- POST -----------------------------------------------------------

    def do_POST(self) -> None:
        parts = urlsplit(self.path)
        if parts.path == "/v1/suites":
            self.handle_create_suite()
            return
        if parts.path == "/v1/cases":
            self.handle_create_case()
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def handle_create_suite(self) -> None:
        try:
            payload = self.read_body()
            suite = self.service.create_suite(payload)
        except ApiError as error:
            self.send_api_error(error)
            return
        self.send_json(201, suite)

    def handle_create_case(self) -> None:
        try:
            payload = self.read_body()
            case = self.service.create_case(payload)
        except ApiError as error:
            self.send_api_error(error)
            return
        self.send_json(201, case)

    # -- DELETE ---------------------------------------------------------

    def do_DELETE(self) -> None:
        parts = urlsplit(self.path)
        path = parts.path
        suite_id = _resource_id(path, "/v1/suites/")
        if suite_id is not None:
            self.handle_delete_suite(suite_id)
            return
        case_id = _resource_id(path, "/v1/cases/")
        if case_id is not None:
            self.handle_delete_case(case_id)
            return
        self.send_json(404, {"error": {"code": "not_found", "message": f"no route for {self.path}"}})

    def handle_delete_suite(self, suite_id: str) -> None:
        try:
            self.service.delete_suite(suite_id)
        except ApiError as error:
            self.send_api_error(error)
            return
        self.send_no_content()

    def handle_delete_case(self, case_id: str) -> None:
        try:
            self.service.delete_case(case_id)
        except ApiError as error:
            self.send_api_error(error)
            return
        self.send_no_content()

    def log_message(self, fmt: str, *args: object) -> None:
        """Silence per-request logging so recorded output stays stable."""


def main() -> int:
    parser = argparse.ArgumentParser(prog="testlattice.server", description="测试、QA 与端到端编排判定平台")
    host, port = env_address()
    parser.add_argument("--host", default=host)
    parser.add_argument("--port", type=int, default=port)
    args = parser.parse_args()
    httpd = ThreadingHTTPServer((args.host, args.port), Handler)
    print(f"TestLattice listening on http://{args.host}:{httpd.server_address[1]}", flush=True)
    try:
        httpd.serve_forever()
    except KeyboardInterrupt:
        pass
    finally:
        httpd.server_close()
    return 0


if __name__ == "__main__":
    raise SystemExit(main())

